/**
 * product.js
 * JSON object containing the product information
 */

const product = {
  name: "Sony WH-1000XM5 Wireless Headphones",
  price: "$399.99",
  description: "Industry-leading noise canceling with two processors, eight microphones, and exceptional high-resolution wireless audio quality with up to 30 hours of battery life.",
  image: "https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=800&auto=format&fit=crop&q=80"
};

export default product;
